import{_ as t,o as a,c as d,a0 as o}from"./chunks/framework.Co68LFjL.js";const h=JSON.parse('{"title":"Framework Example 2: Context Model Index","description":"","frontmatter":{},"headers":[],"relativePath":"examples/framework-example2/domain-models.md","filePath":"examples/framework-example2/domain-models.md"}'),n={name:"examples/framework-example2/domain-models.md"};function i(r,e,s,c,m,l){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="framework-example-2-context-model-index" tabindex="-1">Framework Example 2: Context Model Index <a class="header-anchor" href="#framework-example-2-context-model-index" aria-label="Permalink to &quot;Framework Example 2: Context Model Index&quot;">​</a></h1><p><a href="/ospf/zh-cn/examples/framework-example2/domain-models.html">中文</a></p><p>This index is the documentation boundary for the eleven bounded contexts under <code>framework_demo/demo2</code>. Each linked page describes one context&#39;s domain-model contract in the order defined by the domain-model template. The index is a navigation aid; the context pages remain the place to review variables, intermediates, assertions, constraints, and objectives.</p><h2 id="_1-context-map-and-navigation" tabindex="-1">1. Context map and navigation <a class="header-anchor" href="#_1-context-map-and-navigation" aria-label="Permalink to &quot;1. Context map and navigation&quot;">​</a></h2><p>The dependency direction is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes material-theme-darker material-theme-lighter vp-code" tabindex="0"><code><span class="line"><span>aircraft → stowage → {mac, airworthiness_security, soft_security,</span></span>
<span class="line"><span>                      mac_optimization, express_effectiveness,</span></span>
<span class="line"><span>                      loading_effectiveness, redundancy,</span></span>
<span class="line"><span>                      recommended_weight_equalization, payload_maximization}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>aircraft</code> supplies aircraft, deck, fuel, position, and adjacency data. <code>stowage</code> consumes that configuration and owns item-to-position assignment and load expressions. The remaining contexts consume the shared stowage values for their own balance, safety, effectiveness, or payload responsibilities.</p><h2 id="_2-context-model-pages" tabindex="-1">2. Context model pages <a class="header-anchor" href="#_2-context-model-pages" aria-label="Permalink to &quot;2. Context model pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Context</th><th>Responsibility</th><th>Local model</th></tr></thead><tbody><tr><td><code>aircraft</code></td><td>Aircraft, deck, position, fuel, ULD, and adjacency data</td><td><a href="./domain-aircraft/domain-model.html">Aircraft</a></td></tr><tr><td><code>stowage</code></td><td>Item-position assignment, adjustment, load amount, weight, and core loading limits</td><td><a href="./domain-stowage/domain-model.html">Stowage</a></td></tr><tr><td><code>mac</code></td><td>Torque, CLIM, index, and MAC intermediate values</td><td><a href="./domain-mac/domain-model.html">Mean Aerodynamic Chord (MAC)</a></td></tr><tr><td><code>airworthiness_security</code></td><td>Density, cumulative/zone load, payload, total-weight, envelope, trim, and CLIM limits</td><td><a href="./domain-airworthiness_security/domain-model.html">Airworthiness Security</a></td></tr><tr><td><code>soft_security</code></td><td>Soft empty-position, door, divide-empty, and ballast preferences</td><td><a href="./domain-soft_security/domain-model.html">Soft Security</a></td></tr><tr><td><code>mac_optimization</code></td><td>Longitudinal/lateral balance and horizontal-stabilizer limits and objective</td><td><a href="./domain-mac_optimization/domain-model.html">MAC Optimization</a></td></tr><tr><td><code>express_effectiveness</code></td><td>Must-ship and item-priority ordering</td><td><a href="./domain-express_effectiveness/domain-model.html">Express Effectiveness</a></td></tr><tr><td><code>loading_effectiveness</code></td><td>Source/destination adjacency, loading order, reweigh, trailer, and sequence policies</td><td><a href="./domain-loading_effectiveness/domain-model.html">Loading Effectiveness</a></td></tr><tr><td><code>redundancy</code></td><td>Redundancy and experimental longitudinal-balance limits</td><td><a href="./domain-redundancy/domain-model.html">Redundancy</a></td></tr><tr><td><code>recommended_weight_equalization</code></td><td>Item order, priority appointments, and recommended-weight deviation</td><td><a href="./domain-recommended_weight_equalization/domain-model.html">Recommended Weight Equalization</a></td></tr><tr><td><code>payload_maximization</code></td><td>Maximum payload limit and payload objective</td><td><a href="./domain-payload_maximization/domain-model.html">Payload Maximization</a></td></tr></tbody></table><p>Every page provides a link to its Chinese or English mirror. The parent page documents the exact mode-specific registration boundary.</p><h2 id="_3-mode-registration-notes" tabindex="-1">3. Mode registration notes <a class="header-anchor" href="#_3-mode-registration-notes" aria-label="Permalink to &quot;3. Mode registration notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Contexts in the ordinary model</th><th>Boundary</th></tr></thead><tbody><tr><td><code>LoadingOrder</code></td><td><code>aircraft</code></td><td>Export-only configuration; no meta-model solve</td></tr><tr><td><code>FullLoad</code></td><td><code>stowage</code>, <code>mac</code>, <code>airworthiness_security</code>, <code>soft_security</code>, <code>mac_optimization</code>, <code>express_effectiveness</code>, <code>loading_effectiveness</code></td><td>Airworthiness may be moved to the Benders subproblem</td></tr><tr><td><code>Predistribution</code></td><td>FullLoad contexts plus <code>redundancy</code></td><td>Loading-order pipeline is mode-gated</td></tr><tr><td><code>WeightRecommendation</code></td><td><code>stowage</code>, <code>mac</code>, <code>airworthiness_security</code>, <code>express_effectiveness</code>, <code>recommended_weight_equalization</code>, <code>payload_maximization</code></td><td>Recommendation deviation and payload objective are mode-specific</td></tr></tbody></table><p>The presence of a class or model file in a context does not by itself make a constraint active. Only a pipeline returned by the selected mode&#39;s generator enters that mode&#39;s model.</p>`,13)])])}const f=t(n,[["render",i]]);export{h as __pageData,f as default};
